def parse_vcf(vcf_file_stream, vcf_lines, vcf_headers, add_sname=True, include_ref=False):
    header = ''
    samples = ''

    for l in vcf_file_stream:
        if l[0] == '#':
            if l[1] != '#':
                samples = l.rstrip().split('\t')[9:]
            else:
                # ignore fileDate
                if l[:10] == '##fileDate':
                    continue
                if l not in vcf_headers:
                    vcf_headers.append(l)
        else:
            A = l.rstrip().split('\t')
            if not include_ref and (len(A) > 8 and 'GT' in A[8]):
                has_nonref = False
                for sample_field in A[9:]:
                    if not (sample_field.startswith('0/0') or sample_field.startswith('./.')):
                        has_nonref = True
                        break
                if not has_nonref:
                    continue

            if not 'SECONDARY' in A[7]:

                if add_sname and (samples != []):
                    A[7] += ';' + 'SNAME=' + ','.join(samples)
                    l = '\t'.join(A) + '\n'


                if 'SVTYPE=BND' in A[7]:
                    sep, o_chr, o_pos = parse_bnd_alt_string(A[4])

                    if (o_chr == A[0]) and (('--:' in A[7]) != ('++' in A[7])):
                        neg_s = A[7].find('--:')
                        pos_s = A[7].find('++:')

                        if neg_s > 0:
                            neg_e = neg_s + A[7][neg_s:].find(';')
                            pre=A[7][:neg_s]
                            mid=A[7][neg_s:neg_e]
                            post=A[7][neg_e:]
                            A[7] = pre + '++:0,' + mid + post
                        else:
                            pos_e = pos_s + A[7][pos_s:].find(';')
                            pre=A[7][:pos_s]
                            mid=A[7][pos_s:pos_e]
                            post=A[7][pos_e:]
                            A[7] = pre + mid + ',--:0' + post
                        if ';END=' not in A[7]:
                            A[7] = A[7] + ';END=' + o_pos
                        A[7]=A[7].replace('SVTYPE=BND', 'SVTYPE=INV')
                        A[4] = '<INV>'
                        l = '\t'.join(A) + '\n'
                vcf_lines.append(l)

    return samples

def to_map(s):
    '''
    Convert a string like one would find in a VCF info field to a dictionary
    '''
    m = {}
    for k_v in s.split(';'):
        A = k_v.split('=')
        if len(A) > 1:
            m[A[0]] = A[1]
        else:
            m[A[0]] = None

    return m

def vcf_line_cmp(l1, l2):
    v1 = split_v(l1)
    v2 = split_v(l2)

    v1[3] = v1[3][:2]
    v2[3] = v2[3][:2]

    for i in range(len(v1)-1):
        if v1[i] != v2[i]:
            return cmp(v1[i],v2[i])
    return 0

def header_line_cmp(l1, l2):
    order = ['##source', \
             '##INFO', \
             '##ALT', \
             '##FORMAT',\
             '##SAMPLE']

    # make sure ##fileformat is first
    if l1[:12] == '##fileformat':
        return -1

    if l2[:12] == '##fileformat':
        return 1

    # make sure #CHROM ... is last
    if l1[1] != '#':
        return 1
    elif l2[1] != '#':
        return -1

    if l1.find('=') == -1:
        return -1
    if l2.find('=') == -1:
        return 1

    h1 = l1[:l1.find('=')]
    h2 = l2[:l2.find('=')]
    if h1 not in order:
        return -1
    if h2 not in order:
        return 1
    return cmp(order.index(h1),order.index(h2))

def trim(A):
    '''
    Return offset of first non-zero value from each end of an array
    '''
    clip_start = 0
    for i in range(len(A)):
        if A[i] == 0:
            clip_start += 1
        else:
            break
    clip_end = 0
    for i in range(len(A)-1,-1,-1):
        if A[i] == 0:
            clip_end += 1
        else:
            break
    return [clip_start, clip_end]

def stats_report_string(self):
    return "{0} variants read\n{1} skipped\n{2} pruned\n{3} emitted\n".format(self.bedpe_lines,
        self.skipped_lines,
        self.bedpe_lines - self.skipped_lines - self.emitted_lines,
        self.emitted_lines)

def reciprocal_overlap(a, b_list):
    overlap = 0
    b_aggregate = 0
    # catch divide by zero error
    if a[1] == a[0]:
        return 0

    # update the overlap and b_aggregate
    for b in b_list:
        b_aggregate += (b[1] - b[0])
        overlap += float(min(a[1], b[1]) - max(a[0], b[0]))

    # catch divide by zero error
    if b_aggregate == 0:
        return 0

    return min(overlap / (a[1] - a[0]), overlap / b_aggregate)

def annotation_intersect(var, ae_dict, threshold):
    best_frac_overlap = 0
    best_feature = ''
    slop = 0

    # dictionary with number of bases of overlap for each class
    class_overlap = {}

    # first check for reciprocal overlap
    if var.chrom in ae_dict:
        var_start = var.pos
        var_end = int(var.info['END'])
        i = 0
        while 1:
            # bail if end of dict
            if i >= len(ae_dict[var.chrom]):
                break
            feature = ae_dict[var.chrom][i]
            if feature[0] - slop < var_end:
                if feature[1] + slop > var_start:
                    try:
                        class_overlap[feature[2]].append(feature)
                    except KeyError:
                        class_overlap[feature[2]] = [feature]
            else:
                break
            i += 1

        # print class_overlap
        for me_class in class_overlap:
            class_overlap[me_class] = collapse_bed_records(class_overlap[me_class])
            frac_overlap = reciprocal_overlap([var_start, var_end], class_overlap[me_class])
            if frac_overlap > best_frac_overlap:
                best_frac_overlap = frac_overlap
                best_feature = me_class


        if best_frac_overlap >= threshold:
            return best_feature

    return None

def lld(xx, mean, sd):
    ll = 1 / sd * math.exp(-(xx-mean) * (xx-mean) / (2*sd*sd))
    return ll

def rd_support_nb(temp, p_cnv):
    tr = pd.DataFrame({'p0' : [1.0, 0.1, 0.0], 'p1' : [0.0, 0.7, 0.25], 'p2' : [0.0, 0.2, 0.75], 'GT' : ["0/0", "0/1", "1/1"]})
    temp = pd.merge(temp, tr, on='GT', how='left')
    temp['p_mix'] = temp['lld0'] * temp['p0'] + temp['lld1'] * temp['p1'] + temp['lld2'] * temp['p2']
    return np.log(p_cnv)+np.sum(np.log(temp['p_mix'])) > np.log(1-p_cnv)+np.sum(np.log(temp['lld0']))

def has_rd_support_by_nb(test_set, het_del_fit, hom_del_fit, params, p_cnv = 0.5):
    svtype=test_set['svtype'][0]
    svlen=test_set['svlen'][0]
    log_len=test_set['log_len'][0]

    if svtype == 'DEL' and svlen<1000:
        params1=params[params.svtype=='DEL'].copy()
        if svlen<50:
            params1['log_len']=math.log(50)
        else:
            params1['log_len']=log_len
        params1.loc[:,'mean1_adj'] = params1.loc[:,'mean1'] + het_del_fit.predict(params1)
        params1.loc[:,'mean2_adj'] = params1.loc[:,'mean2'] + hom_del_fit.predict(params1)
    else:
        params1=params.copy()
        params1.loc[:,'mean1_adj'] = params1.loc[:,'mean1']
        params1.loc[:,'mean2_adj'] = params1.loc[:,'mean2']

    v0=test_set.loc[test_set.GT=="0/0", 'log2r'].values
    v1=test_set.loc[test_set.GT=="0/1", 'log2r'].values
    v2=test_set.loc[test_set.GT=="1/1", 'log2r'].values

    if len(v0)>0:
        med0=np.median(v0)
    else:
        if len(v1)>0:
            med0=med1=np.median(v1)
        elif len(v2)>0:
            med0=med1=med2=np.median(v2)
        else:
            return False

    if len(v1)>0:
        med1=np.median(v1)
    else:
        med1=med0
    if len(v2)>0:
        med2=np.median(v2)
    else:
        med2=med1

    if svtype=='DEL' and ( med1>med0 or med2>med0 ):
        return False
    elif svtype=='DUP' and (med1<med0 or med2<med0):
        return False

    mm=pd.merge(test_set, params1, how='left')

    mm.loc[:,'lld0'] = mm.apply(lambda row:lld(row["log2r"], row["mean0"],row["std_pooled"]), axis=1)
    mm.loc[:,'lld1'] = mm.apply(lambda row:lld(row["log2r"], row["mean1_adj"],row["std_pooled"]), axis=1)
    mm.loc[:,'lld2'] = mm.apply(lambda row:lld(row["log2r"], row["mean2_adj"],row["std_pooled"]), axis=1)

    return  rd_support_nb(mm, p_cnv)

def load_df(var, exclude, sex, sex_chrom_names):

    epsilon = 0.1
    test_set = list()

    for s in var.sample_list:
        if s in exclude:
            continue
        cn = var.genotype(s).get_format('CN')
        if (var.chrom in sex_chrom_names) and sex[s] == 1:
            cn = str(float(cn) * 2)
        log2r = math.log((float(cn)+epsilon)/2, 2)  # to avoid log(0)
        test_set.append(CN_rec(var.var_id, s, var.info['SVTYPE'], abs(float(var.info['SVLEN'])), var.info['AF'],
             var.genotype(s).get_format('GT'),  cn , var.genotype(s).get_format('AB'), math.log(abs(float(var.info['SVLEN'])+epsilon)), log2r))

    test_set = pd.DataFrame(data = test_set, columns=CN_rec._fields)
    return test_set

def has_low_freq_depth_support(test_set, mad_threshold=2, absolute_cn_diff=0.5):

    mad_quorum = 0.5 # this fraction of the pos. genotyped results must meet the mad_threshold

    hom_ref_cn=test_set[test_set.GT=="0/0"]['CN'].values.astype(float)
    hom_het_alt_cn=test_set[(test_set.GT=="0/1") | (test_set.GT=="1/1")]['CN'].values.astype(float)

    if len(hom_ref_cn) > 0:
        cn_median = np.median(hom_ref_cn)
        cn_mad = mad(hom_ref_cn)
    else:
        cn_median = None
        cn_mad = None

    # bail after writing out diagnostic info, if no ref samples or all ref samples
    if (len(hom_ref_cn) == 0 or len(hom_het_alt_cn) == 0):
        return False

    # tally up the pos. genotyped samples meeting the mad_threshold

    resid=hom_het_alt_cn-cn_median
    #if test_set['svtype'][0]=='DEL':
    if test_set.loc[0, 'svtype']=='DEL':
        resid=-resid

    resid=resid[(resid > (cn_mad * mad_threshold) ) & (resid>absolute_cn_diff)]

    if float(len(resid))/len(hom_het_alt_cn)>mad_quorum:
        return True
    else:
        return False

def has_high_freq_depth_support(df, slope_threshold, rsquared_threshold):

    rd = df[[ 'AB', 'CN']][df['AB']!='.'].values.astype(float)
    if len(np.unique(rd[:,0])) > 1 and len(np.unique(rd[:,1])) > 1:

        (slope, intercept, r_value, p_value, std_err) = stats.linregress(rd)
        if df['svtype'][0] == 'DEL':
            slope=-slope
        #sys.stderr.write(df['var_id'][0]+"\t"+str(slope)+"\t"+str(r_value)+"\n")

        if (slope < slope_threshold or r_value*r_value < rsquared_threshold):
            return False
        return True
    return False

def has_rd_support_by_ls(df, slope_threshold, rsquared_threshold, num_pos_samps, mad_threshold=2, absolute_cn_diff=0.5):

    min_pos_samps_for_regression=10
    if num_pos_samps>min_pos_samps_for_regression:
        return has_high_freq_depth_support(df, slope_threshold, rsquared_threshold)
    else:
        return has_low_freq_depth_support(df, mad_threshold, absolute_cn_diff)
    return False

def has_rd_support_hybrid(df, het_del_fit, hom_del_fit, params, p_cnv, slope_threshold, rsquared_threshold, num_pos_samps):

    hybrid_support=False
    nb_support=has_rd_support_by_nb(df, het_del_fit, hom_del_fit, params, p_cnv)
    ls_support=has_rd_support_by_ls(df, slope_threshold, rsquared_threshold, num_pos_samps)

    if nb_support and ls_support:
        hybrid_support=True
    elif nb_support and has_rd_support_by_ls(df, 2*slope_threshold, 2*rsquared_threshold, num_pos_samps, 2, 0.75):
        hybrid_support=True
    elif ls_support and has_rd_support_by_nb(df, het_del_fit, hom_del_fit, params, 0.2*p_cnv):
        hybrid_support=True
    return [ls_support, nb_support, hybrid_support]

def sv_classify(vcf_in, vcf_out, gender_file, sex_chrom_names, exclude_file, ae_dict, f_overlap, slope_threshold, rsquared_threshold, p_cnv, het_del_fit, hom_del_fit, params, diag_outfile, method):

    vcf = Vcf()
    header = []
    in_header = True
    sex = {}
    # read sample genders
    for line in gender_file:
        v = line.rstrip().split('\t')
        sex[v[0]] = int(v[1])

    exclude = []
    if exclude_file is not None:
        for line in exclude_file:
            exclude.append(line.rstrip())

    if diag_outfile is not None:
        outf=open(diag_outfile, 'w', 4096)
        outf.write("varid\torig_svtype\tsvlen\tnum_pos_samps\tnb_support\tls_support\thybrid_support\thas_rd_support\n")

    for line in vcf_in:
        if in_header:
            if line[0] == '#':
                header.append(line)
                continue
            else:
                in_header = False
                vcf.add_header(header)
                vcf_out.write(vcf.get_header() + '\n')

        v = line.rstrip().split('\t')
        info = v[7].split(';')
        svtype = None
        for x in info:
            if x.startswith('SVTYPE='):
                svtype = x.split('=')[1]
                break
        # bail if not DEL or DUP prior to reclassification
        if svtype not in ['DEL', 'DUP']:
            vcf_out.write(line)
            continue

        var = Variant(v, vcf)

        # check intersection with mobile elements
        if ae_dict is not None and var.info['SVTYPE'] in ['DEL']:
            ae = annotation_intersect(var, ae_dict, f_overlap)
            if ae is not None:
                if ae.startswith('SINE') or ae.startswith('LINE') or ae.split('|')[2].startswith('SVA'):
                    ae = 'ME:' + ae
                var.alt = '<DEL:%s>' % ae
                var.info['SVTYPE'] = 'MEI'
                vcf_out.write(var.get_var_string(True) + '\n')
                continue

        #count positively genotyped samples
        num_pos_samps = 0
        num_total_samps=len(var.sample_list)

        for s in var.sample_list:
            if var.genotype(s).get_format('GT') not in ["./.", "0/0"]:
                num_pos_samps += 1

        nb_support = False
        ls_support = False
        hybrid_support = False
        has_rd_support = False

        if num_pos_samps == 0:
            vcf_out.write(line)
        else:
            df = load_df(var, exclude, sex, sex_chrom_names)
            if method == 'large_sample':
                ls_support = has_rd_support_by_ls(df, slope_threshold, rsquared_threshold, num_pos_samps)
                has_rd_support = ls_support
            elif method == 'naive_bayes':
                nb_support = has_rd_support_by_nb(df, het_del_fit, hom_del_fit, params, p_cnv)
                has_rd_support = nb_support
            elif method == 'hybrid':
                ls_support, nb_support, hybrid_support = has_rd_support_hybrid(
                        df,
                        het_del_fit,
                        hom_del_fit,
                        params, p_cnv,
                        slope_threshold,
                        rsquared_threshold,
                        num_pos_samps
                        )
                has_rd_support=hybrid_support

            if has_rd_support:
               vcf_out.write(line)
            else:
                for m_var in to_bnd_strings(var, True):
                    vcf_out.write(m_var + '\n')

            if diag_outfile is not None:
              svlen=df['svlen'][0]
              outf.write(
                      '\t'.join((
                          var.var_id,
                          svtype,
                          str(svlen),
                          str(num_pos_samps),
                          str(nb_support),
                          str(ls_support),
                          str(hybrid_support),
                          str(has_rd_support)
                          )) + "\n"
                      )

    vcf_out.close()
    if diag_outfile is not None:
        outf.close()
    vcf_in.close()
    vcf_out.close()
    gender_file.close()
    if exclude_file is not None:
        exclude_file.close()

    return

def get_ae_dict(ae_path):
    if ae_path.endswith('.gz'):
        ae_bedfile = gzip.open(ae_path, 'rb')
    else:
        ae_bedfile = open(ae_path, 'r')
    ae_dict = {}
    for line in ae_bedfile:
        v = line.rstrip().split('\t')
        if len(v) < 4:
            continue
        v[1] = int(v[1])
        v[2] = int(v[2])
        if v[0] in ae_dict:
            ae_dict[v[0]].append(v[1:])
        else:
            ae_dict[v[0]] = [v[1:]]
    ae_bedfile.close()
    return ae_dict

def chromosome_prefix(chrom):
    if chrom.startswith('chr'):
        # Add a non-chr version
        return chrom[3:]
    else:
        return 'chr' + chrom

def __init__(self, string = None, tempdir = None):
    '''Create a new wrapper around a stream'''
    self.tempdir = tempdir
    if string in (None, '-', 'stdin') and self.valid(string):
        self.handle = sys.stdin
        return
    if string.startswith('gs:'):
        localpath = self.download_google_file(string)
        string = localpath
    if string.endswith('.gz'):
        import gzip
        self.handle = gzip.open(string, 'rb')
    else:
        self.handle = open(string, 'r')

def md5(self, filepath):
    with open(filepath, 'rb') as fh:
        m = hashlib.md5()
        while True:
            data = fh.read(8192) # 8kb chunk
            if not data:
                break
            m.update(data)
        return m.hexdigest()

def md5s_match(self, localpath, cloud_md5):
    hexdigest = self.md5(localpath)
    return hexdigest == cloud_md5

def readline(self):
    l = self.handle.readline()
    return l

def valid(string):
    '''Check if we allow the opening of stdin'''
    if string is None and sys.stdin.isatty():
        raise IOError('no input specified but terminal is interactive')
    return True

def __enter__(self):
    '''Support use of with by passing back the originating handle'''
    return self.handle

def __exit__(self, *kwargs):
    '''Support use of with by closing on exit of the context'''
    self.handle.close()

def __iter__(self):
    '''Support use in loops like a normal file object'''
    return self.handle.__iter__()

def close(self):
    '''Close the underlying handle'''
    return self.handle.close()

