    if len(BP) == 1:
       #merge a single breakpoint
        v_id+=1
        var=merge_single_bp(BP, sample_order, v_id, use_product, vcf, vcf_out, include_genotypes)
        write_var(var, vcf_out, include_genotypes)

    else:

        BP.sort(key=lambda x: x.left.start)
        ordered_cliques = []
