def numeric_alleles(gt_string):
    '''
    Convert a VCF allele string into integers
    '''
    gt = gt_string.split('/')
    if len(gt) == 1:
        gt = gt_string.split('|')
    return map(int, gt)

def execute(self, output_handle=sys.stdout):
    in_header = True
    header = []
    vcf = Vcf()
    vcf_out = output_handle

    # read input VCF
    for line in self.vcf_stream:
        if in_header:
            if line.startswith('##'):
                header.append(line) 
                continue
            elif line.startswith('#CHROM'):
                v = line.rstrip().split('\t')
                header.append('\t'.join(v))

                in_header = False
                vcf.add_header(header)

                vcf.add_info('AF', 'A', 'Float', 'Allele Frequency, for each ALT allele, in the same order as listed')
                vcf.add_info('NSAMP', '1', 'Integer', 'Number of samples with non-reference genotypes')
                vcf.add_info('MSQ', '1', 'Float', 'Mean sample quality of positively genotyped samples')

                # write header
                vcf_out.write(vcf.get_header() + '\n')
                #vcf_out.write('\t' + '\t'.join(v[8:]) + '\n')
            continue

        v = line.rstrip().split('\t')
        var = Variant(v, vcf)

        # extract genotypes from VCF
        num_alt = len(var.alt.split(','))
        alleles = [0] * (num_alt + 1)
        num_samp = 0
        sum_sq = 0.0

        for gt in var.genotypes():
            gt_string = gt.get_format('GT')

            if '.' not in gt_string:
                indexes = self.numeric_alleles(gt_string)

                for i in indexes:
                    alleles[i] += 1

                # iterate the number of non-reference samples
                if sum(indexes) > 0:
                    num_samp += 1
                    try:
                        sum_sq += float(gt.get_format('SQ'))
                    except KeyError:
                        pass

        allele_sum = float(sum(alleles))
        allele_freq = ['.'] * len(alleles)

        # populate AF
        if allele_sum > 0:
            for i in xrange(len(alleles)):
                allele_freq[i] = alleles[i] / allele_sum
            var.info['AF'] = ','.join(map(str, ['%.4g' % a for a in allele_freq[1:]]))
        else:
            var.info['AF'] = ','.join(map(str, allele_freq[1:]))

        # populate NSAMP
        var.info['NSAMP'] = num_samp
        if num_samp > 0:
            msq = '%0.2f' % (sum_sq / num_samp)
        else:
            msq = '.'
        var.info['MSQ'] = msq

        # after all samples have been processed, write
        vcf_out.write(var.get_var_string(use_cached_gt_string=True) + '\n')
    vcf_out.close()

def find_tag(info_string, tag):
    tag_start = info_string.find(tag)
    while tag_start != -1 and (tag_start > 0 and info_string[tag_start-1] != ';'):
        tag_start = info_string.find(tag, tag_start+1)
    return tag_start

def parse_score(score):
    if score.isdigit():
        return float(score)
    else:
        return score

def info(self):
    '''
    Return the appropriate info field if only one is required. Info from the primary variant is preferred if available.
    '''
    if self.info1 == 'MISSING':
        return self.info2
    else:
        return self.info1

def set_info(self, field, value):
    '''
    Add the info field to the BEDPE line info fields. As BEDPE lines don't know about their headers this is not a safe operation.
    Doesn't add to info field if it is the null character. Probably this is wrong.
    '''
    new_tag = ';' + str(field);
    if value is not None:
        new_tag += '=' + str(value)
    if self.malformedFlag != 1:
        self.info1 = self.info1 + new_tag
    if self.malformedFlag != 2 and self.info2 != '.':
        self.info2 = self.info2 + new_tag

def check_malformed(self):
    if self.info1 == 'MISSING':
        self.malformedFlag = 1
    if self.info2 == 'MISSING':
        self.malformedFlag = 2

def retrieve_svtype(self):
    try:
        svtype = re.split('=', ''.join(filter(lambda x: x.startswith('SVTYPE='), self.info.split(';'))))[1]
    except IndexError:
        raise ValueError('SVTYPE field not present in INFO field')
    return svtype

def retrieve_af(self):
    try:
        af = re.split('=', ''.join(filter(lambda x: x.startswith('AF='), self.info.split(';'))))[1]
    except IndexError:
        af = None
    return af

def sname_value(info_string):
    '''
    Retrieves the SNAME value from an info_string. Static method so we can
    easily do it for either info1 or info2 on demand
    '''
    value = Bedpe.parse_info_tag(info_string, 'SNAME=')
    if value in (False, True):
        return None
    else:
        return value

def _update_sname_field(original_info1, original_info2):
    '''
    Update the sname field in the original info string by adding
    values from the another info string
    '''
    new_sname = Bedpe._combine_sname_values(
            Bedpe.sname_value(original_info1),
            Bedpe.sname_value(original_info2))
    if new_sname:
        return Bedpe.update_info_tag(original_info1, 'SNAME=', new_sname)
    else:
        return original_info1

