def adjust_coordinate(vcf_variant, info_tag, start, end):
    '''
    Return adjusted start and end coordinates according to the contents
    of the tag (if it exists)
    '''
    if info_tag in vcf_variant.info:
        span = map(int, vcf_variant.info[info_tag].split(','))
        if len(span) != 2:
            raise ValueError('Invalid value for tag {0}. Require 2 values to adjust coordinates.'.format(info_tag))
        return (start + span[0], end + span[1])
    else:
        return (start, end)

def register_vcs_handler(vcs, method):  # decorator
    """Decorator to mark a method as the handler for a particular VCS."""
    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def decorate(f):
    """Store f in HANDLERS[vcs][method]."""
    if vcs not in HANDLERS:
        HANDLERS[vcs] = {}
    HANDLERS[vcs][method] = f
    return f

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False):
    """Call the given command(s)."""
    assert isinstance(commands, list)
    p = None
    for c in commands:
        try:
            dispcmd = str([c] + args)
            # remember shell=False, so use git.cmd on windows, not just git
            p = subprocess.Popen([c] + args, cwd=cwd, stdout=subprocess.PIPE,
                                 stderr=(subprocess.PIPE if hide_stderr
                                         else None))
            break
        except EnvironmentError:
            e = sys.exc_info()[1]
            if e.errno == errno.ENOENT:
                continue
            if verbose:
                print("unable to run %s" % dispcmd)
                print(e)
            return None
    else:
        if verbose:
            print("unable to find command, tried %s" % (commands,))
        return None
    stdout = p.communicate()[0].strip()
    if sys.version_info[0] >= 3:
        stdout = stdout.decode()
    if p.returncode != 0:
        if verbose:
            print("unable to run %s (error)" % dispcmd)
        return None
    return stdout

def versions_from_parentdir(parentdir_prefix, root, verbose):
    """Try to determine the version from the parent directory name.

    Source tarballs conventionally unpack into a directory that includes
    both the project name and a version string.
    """
    dirname = os.path.basename(root)
    if not dirname.startswith(parentdir_prefix):
        if verbose:
            print("guessing rootdir is '%s', but '%s' doesn't start with "
                  "prefix '%s'" % (root, dirname, parentdir_prefix))
        raise NotThisMethod("rootdir doesn't start with parentdir_prefix")
    return {"version": dirname[len(parentdir_prefix):],
            "full-revisionid": None,
            "dirty": False, "error": None}

def git_get_keywords(versionfile_abs):
    """Extract version information from the given file."""
    # the code embedded in _version.py can just fetch the value of these
    # keywords. When used from setup.py, we don't want to import _version.py,
    # so we do it with a regexp instead. This function is not used from
    # _version.py.
    keywords = {}
    try:
        f = open(versionfile_abs, "r")
        for line in f.readlines():
            if line.strip().startswith("git_refnames ="):
                mo = re.search(r'=\s*"(.*)"', line)
                if mo:
                    keywords["refnames"] = mo.group(1)
            if line.strip().startswith("git_full ="):
                mo = re.search(r'=\s*"(.*)"', line)
                if mo:
                    keywords["full"] = mo.group(1)
        f.close()
    except EnvironmentError:
        pass
    return keywords

def git_versions_from_keywords(keywords, tag_prefix, verbose):
    """Get version information from git keywords."""
    if not keywords:
        raise NotThisMethod("no keywords at all, weird")
    refnames = keywords["refnames"].strip()
    if refnames.startswith("$Format"):
        if verbose:
            print("keywords are unexpanded, not using")
        raise NotThisMethod("unexpanded keywords, not a git-archive tarball")
    refs = set([r.strip() for r in refnames.strip("()").split(",")])
    # starting in git-1.8.3, tags are listed as "tag: foo-1.0" instead of
    # just "foo-1.0". If we see a "tag: " prefix, prefer those.
    TAG = "tag: "
    tags = set([r[len(TAG):] for r in refs if r.startswith(TAG)])
    if not tags:
        # Either we're using git < 1.8.3, or there really are no tags. We use
        # a heuristic: assume all version tags have a digit. The old git %d
        # expansion behaves like git log --decorate=short and strips out the
        # refs/heads/ and refs/tags/ prefixes that would let us distinguish
        # between branches and tags. By ignoring refnames without digits, we
        # filter out many common branch names like "release" and
        # "stabilization", as well as "HEAD" and "master".
        tags = set([r for r in refs if re.search(r'\d', r)])
        if verbose:
            print("discarding '%s', no digits" % ",".join(refs-tags))
    if verbose:
        print("likely tags: %s" % ",".join(sorted(tags)))
    for ref in sorted(tags):
        # sorting will prefer e.g. "2.0" over "2.0rc1"
        if ref.startswith(tag_prefix):
            r = ref[len(tag_prefix):]
            if verbose:
                print("picking %s" % r)
            return {"version": r,
                    "full-revisionid": keywords["full"].strip(),
                    "dirty": False, "error": None
                    }
    # no suitable tags, so version is "0+unknown", but full hex is still there
    if verbose:
        print("no suitable tags, using unknown + full revision id")
    return {"version": "0+unknown",
            "full-revisionid": keywords["full"].strip(),
            "dirty": False, "error": "no suitable tags"}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if "+" in pieces.get("closest-tag", ""):
        return "."
    return "+"

def render_pep440_pre(pieces):
    """TAG[.post.devDISTANCE] -- No -dirty.

    Exceptions:
    1: no tags. 0.post.devDISTANCE
    """
    if pieces["closest-tag"]:
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += ".post.dev%d" % pieces["distance"]
    else:
        # exception #1
        rendered = "0.post.dev%d" % pieces["distance"]
    return rendered

def render_pep440_old(pieces):
    """TAG[.postDISTANCE[.dev0]] .

    The ".dev0" means dirty.

    Eexceptions:
    1: no tags. 0.postDISTANCE[.dev0]
    """
    if pieces["closest-tag"]:
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += ".post%d" % pieces["distance"]
            if pieces["dirty"]:
                rendered += ".dev0"
    else:
        # exception #1
        rendered = "0.post%d" % pieces["distance"]
        if pieces["dirty"]:
            rendered += ".dev0"
    return rendered

def render_git_describe(pieces):
    """TAG[-DISTANCE-gHEX][-dirty].

    Like 'git describe --tags --dirty --always'.

    Exceptions:
    1: no tags. HEX[-dirty]  (note: no 'g' prefix)
    """
    if pieces["closest-tag"]:
        rendered = pieces["closest-tag"]
        if pieces["distance"]:
            rendered += "-%d-g%s" % (pieces["distance"], pieces["short"])
    else:
        # exception #1
        rendered = pieces["short"]
    if pieces["dirty"]:
        rendered += "-dirty"
    return rendered

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if pieces["error"]:
        return {"version": "unknown",
                "full-revisionid": pieces.get("long"),
                "dirty": None,
                "error": pieces["error"]}

    if not style or style == "default":
        style = "pep440"  # the default

    if style == "pep440":
        rendered = render_pep440(pieces)
    elif style == "pep440-pre":
        rendered = render_pep440_pre(pieces)
    elif style == "pep440-post":
        rendered = render_pep440_post(pieces)
    elif style == "pep440-old":
        rendered = render_pep440_old(pieces)
    elif style == "git-describe":
        rendered = render_git_describe(pieces)
    elif style == "git-describe-long":
        rendered = render_git_describe_long(pieces)
    else:
        raise ValueError("unknown style '%s'" % style)

    return {"version": rendered, "full-revisionid": pieces["long"],
            "dirty": pieces["dirty"], "error": None}

def get_versions():
    """Get version information or return default if unable to do so."""
    # I am in _version.py, which lives at ROOT/VERSIONFILE_SOURCE. If we have
    # __file__, we can work backwards from there to the root. Some
    # py2exe/bbfreeze/non-CPython implementations don't do __file__, in which
    # case we can only use expanded keywords.

    cfg = get_config()
    verbose = cfg.verbose

    try:
        return git_versions_from_keywords(get_keywords(), cfg.tag_prefix,
                                          verbose)
    except NotThisMethod:
        pass

    try:
        root = os.path.realpath(__file__)
        # versionfile_source is the relative path from the top of the source
        # tree (where the .git directory might live) to this file. Invert
        # this to find the root from __file__.
        for i in cfg.versionfile_source.split('/'):
            root = os.path.dirname(root)
    except NameError:
        return {"version": "0+unknown", "full-revisionid": None,
                "dirty": None,
                "error": "unable to find root of source tree"}

    try:
        pieces = git_pieces_from_vcs(cfg.tag_prefix, root, verbose)
        return render(pieces, cfg.style)
    except NotThisMethod:
        pass

    try:
        if cfg.parentdir_prefix:
            return versions_from_parentdir(cfg.parentdir_prefix, root, verbose)
    except NotThisMethod:
        pass

    return {"version": "0+unknown", "full-revisionid": None,
            "dirty": None,
            "error": "unable to compute version"}

def add_header(self, header):
    '''
    Populate the meta information by reading the header
    '''
    # XXX We could probably simplify the below by making a dict of our supported keys
    # and have the values by method/function references for the action
    for line in header:
        split_header = line.split('=')
        if split_header[0] == '##fileformat':
            self.file_format = line.rstrip().split('=')[1]
        elif split_header[0] == '##fileDate':
            self.other_meta.append('##fileDate=' + time.strftime('%Y%m%d'))
        elif split_header[0] == '##INFO':
            self.add_info(*[b.split('=')[1] for b in self.parse_meta(line)])
        elif split_header[0] == '##ALT':
            self.add_alt(*[b.split('=')[1] for b in self.parse_meta(line)])
        elif split_header[0] == '##FORMAT':
            self.add_format(*[b.split('=')[1] for b in self.parse_meta(line)])
        elif split_header[0] == '##FILTER':
            self.add_filter(*[b.split('=')[1] for b in self.parse_meta(line)])
        elif split_header[0].startswith('##'):
            self.other_meta.append(line.rstrip())
        elif line[0] == '#' and line[1] != '#':
            self.sample_list = line.rstrip().split('\t')[9:]
            for i in xrange(0, len(self.sample_list)):
                if self.sample_list[i] not in self.sample_indices:
                    self.sample_indices[self.sample_list[i]] = i + 9
                else:
                    sys.stderr.write('\nError: Duplicate sample ({0}) detected in input VCF. Make certain all sample names are unique.\n'.format(self.sample_list[i]))
                    sys.exit(1)

def set_format(self, field, value):
    '''
    Set information for an individual format field.
    '''
    if field in self.variant.format_set:
        if field in self.variant.format_dict:
            i = self.variant.format_dict[field]
            self._set_value(i, value)
        else:
            num_fields = len(self.variant.format_dict)
            self.variant.format_dict[field] = num_fields
            self._set_value(num_fields, value)
    else:
        sys.stderr.write('\nError: invalid FORMAT field, \"' + field + '\"\n')
        sys.exit(1)

def _set_value(self, index, value):
    try:
        self.value_list[index] = value
    except IndexError:
        self.value_list.extend(['.'] * (index - len(self.value_list)))
        self.value_list.append(value)

def get_format(self, field):
    '''
    Get value of particular field key
    '''
    try:
        return self.value_list[self.variant.format_dict[field]]
    except IndexError:
        if field != 'GT':
            return '.'
        else:
            return './.'

def get_gt_string(self):
    '''
    Convert object back to string.

    If some values are missing (at the end for example) they are printed out as
    all format fields present in any Genotype instance in the Variant line
    are tracked.
    '''
    g_list = list()
    for f in self.variant.format_list:
        if f.id in self.variant.format_dict:
            value = self.get_format(f.id)
            if type(value) == float:
                g_list.append('%0.2f' % value)
            else:
                g_list.append(str(value))
    return ':'.join(g_list)

def set_info(self, field, value):
    '''
    Set value of the specified field in the INFO section.
    The INFO field must exist already.
    '''
    if field in [i.id for i in self.info_list]:
        self.info[field] = value
    else:
        sys.stderr.write('\nError: invalid INFO field, \"' + field + '\"\n')
        exit(1)

def get_info_string(self):
    '''
    Construct the INFO string for printing. Order is matched to the header.
    '''
    i_list = list()
    for info_field in self.info_list:
        if info_field.id in self.info.keys():
            if info_field.type == 'Flag':
                if self.info[info_field.id]:
                    i_list.append(info_field.id)
            else:
                i_list.append('%s=%s' % (info_field.id, self.info[info_field.id]))
    return ';'.join(i_list)

def get_format_string(self, use_cached_format_string=False):
    '''
    Construct the FORMAT field containing the names of the fields in the Genotype columns
    If 8-column VCF then format_string will be None
    '''
    if use_cached_format_string or self.gts is None:
        return self.format_string
    else:
        f_list = list()
        for f in self.format_list:
            if f.id in self.format_dict:
                f_list.append(f.id)
        return ':'.join(f_list)

def get_gt_string(self, use_cached_gt_string=False):
    '''
    Construct the genotype string.
    If 8-column VCF then this returns None
    '''
    if self.gts:
        if use_cached_gt_string:
            return self.gts_string
        else:
            return '\t'.join(self.genotype(s).get_gt_string() for s in self.sample_list)
    else:
        return self.gts_string

def genotypes(self):
    '''
    Return a list of all genotype data in the Variant line
    Returns an empty list if 8-column VCF
    '''
    self._uncache_gts()
    if self.gts is not None:
        return self.gts.values()
    else:
        return list()

def genotype(self, sample_name):
    '''
