    Formats the specified value from this column for printing.
    """
    if v is None:
        s = "NA"
    else:
        n = self.get_num_elements()
        if self.get_type() == WT_CHAR:
            s = v.decode()
        elif n == 1:
            s = str(v)
        else:
            s = ",".join(str(u) for u in v)
            s = "(" + s + ")"
    return s

