def run(self):
    counter = self._index.counter()
    cols = self._index.key_columns()
    n = len(cols)
    s = "\t".join([cols[j].get_name() for j in range(n)])
    s = "n\t" + s
    print("#", s)
    for k, v in counter.items():
        if n == 1:
            s = cols[0].format_value(k)
        else:
            s = "\t".join([cols[j].format_value(k[j]) for j in range(n)])
        print(v, "\t",  s)

