        v = self._start
        start = 0 if v is None else v[0]
        v = self._stop
        stop = v if v is None else v[0]
        cursor = self._table.cursor(self._columns, start, stop)
    else:
        start = self._start
        stop = self._stop
        cursor = self._index.cursor(self._columns, start, stop)
    for row in cursor:
        s = ""
        for c, v in zip(self._columns, row):
            s = s + c.format_value(v) + "\t"
        print(s)

def cleanup(self):
    if self._index is not None:
        if self._index.is_open():
            self._index.close()
    super(DumpRunner, self).cleanup()

def get_os():
    if 'win' in platform.system().lower():
        WIN_PLATFORM_NONFREE = True

def _make_gen(reader):
    b = reader(1024 * 1024)
    while b:
        yield b
        b = reader(1024 * 1024)

def get_linecount(fname):
    f = open(fname, 'rb')
    f_gen = _make_gen(f.read)

    return sum(buf.count(b'\n') for buf in f_gen)

def substitute_dots(line):
  """
  Whenever a value in a subfield of the INFO field is '.', replace it with a
  'nan'.
  """
  try:
      line_s = line.strip('\r\n').split('\t')
      info = {(item.split('=')[0] if item.find('=')!= -1
    	else item):(item.split('=')[1] if item.find('=')!= -1
    	else 'nan') for item in line_s[7].split(';')}

      for key in info:
        values = list()
        for val in info[key].split(','):
          if val == '.':
            values.append('nan')
          else:
            values.append(val)
        info[key] = ','.join(values)
      new_info = ''
      for k in info:
        new_info += k + '=' + info[k] + ';'
      new_info = new_info[:-1]
      new_line = '\t'.join([line_s[0], line_s[1], line_s[2], line_s[3], line_s[4],
                            line_s[5], line_s[6], new_info]) + '\t' + \
                 '\t'.join(line_s[8:]) + '\n'
      return new_line

  except:
      #this VCF is mangled, or it isn't a VCF
      raise #return to caller

def run(self):
    """
    Top level entry point.
    """
    if os.path.exists(self.__destination):
        if self.__force:
            if os.path.isdir(self.__destination):
                shutil.rmtree(self.__destination)
            else:
                os.unlink(self.__destination)
        else:
            s = "'{0}' exists; use -f to overwrite".format(self.__destination)
            self.error(s)
    self.write_table()

def __str__(self):
    s = "NULL Column"
    if self.__ll_object is not None:
        s = "'{0}':{1}({2})".format(self.get_name(), self.get_type_name(),
                self.get_num_elements())
    return s

def get_name(self):
    """
    Returns the name of this column. This is the unique identifier for
    a column.
    """
    return self.__ll_object.name.decode()

def get_description(self):
    """
    Returns the description of this column. This is an optional string
    describing the purpose of a column.
    """
    return self.__ll_object.description.decode()

def format_value(self, v):
    """
    Formats the specified value from this column for printing.
    """
    if v is None:
        s = "NA"
    else:
        n = self.get_num_elements()
        if self.get_type() == WT_CHAR:
            s = v.decode()
        elif n == 1:
            s = str(v)
        else:
            s = ",".join(str(u) for u in v)
            s = "(" + s + ")"
    return s

def get_xml(self):
    """
    Returns an ElementTree.Element representing this Column.
    """
    n = self.get_num_elements()
    if n == WT_VAR_1:
        num_elements = "var(1)"
    elif n == WT_VAR_2:
        num_elements = "var(2)"
    else:
        num_elements = str(self.get_num_elements())
    d = {
        "name":self.get_name(),
        "description":self.get_description(),
        "element_size":str(self.get_element_size()),
        "num_elements":num_elements,
        "element_type":self.get_type_name()
    }
    return ElementTree.Element("column", d)

def parse_xml(theclass, xmlcol):
    """
    Parses the specified XML column description and returns a new
    Column instance.
    """
    reverse = {}
    for k, v in theclass.ELEMENT_TYPE_STRING_MAP.items():
        reverse[v] = k
    if xmlcol.tag != "column":
        raise ValueError("invalid xml")
    name = xmlcol.get("name").encode()
    description = xmlcol.get("description").encode()
    # TODO some error checking here.
    element_size = int(xmlcol.get("element_size"))
    s = xmlcol.get("num_elements")
    if s == "var(1)":
        num_elements = WT_VAR_1
    elif s == "var(2)":
        num_elements = WT_VAR_2
    else:
        num_elements = int(s)
    element_type = reverse[xmlcol.get("element_type")]
    col = _wormtable.Column(name, description, element_type, element_size,
            num_elements)
    return theclass(col)

def __del__(self):
    if self.is_open():
        # TODO add in a logging.warning message here.
        # print("closing dangling table.", self.__ll_object)
        try:
            self.__ll_object.close()
        finally:
            self.__ll_object = None

def get_metadata_path(self):
    """
    Returns the path of the file used to store metadata for the
    database.
    """
    return os.path.join(self.get_homedir(), self.get_db_name() + ".xml")

def verify_closed(self):
    """
    Ensures this database is closed.
    """
    if self.is_open():
        raise ValueError("Database must be closed")

def verify_open(self, mode=None):
    """
    Ensures this database is open in the specified mode..
    """
    if mode is None:
        if not self.is_open():
            raise ValueError("Database must be opened")
    else:
        if self.__open_mode != mode or not self.is_open():
            m = {WT_WRITE: "write", WT_READ: "read"}
            s = "Database must be opened in {0} mode".format(m[mode])
            raise ValueError(s)

def columns(self):
    """
    Returns the list of columns in this table.
    """
    return list(self.__columns)

def translate_columns(self, columns):
    """
    Translates the specified list of column identifiers into a list
    of Column instances. Column identifiers may be strings, integers
    or Column instances.
    """
    cols = []
    for col_id in columns:
        if isinstance(col_id, Column):
            cols.append(col_id)
        elif isinstance(col_id, int):
            cols.append(self.__columns[col_id])
        else:
            cols.append(self.get_column(col_id))
    return cols

def get_metadata(self):
    """
    Returns an ElementTree instance describing the metadata for this
    Table.
    """
    d = {"version":TABLE_METADATA_VERSION}
    root = ElementTree.Element("table", d)
    root.append(self._generate_schema_xml())
    root.append(self._generate_stats_xml())
    return ElementTree.ElementTree(root)

def _parse_stats_xml(self, stats):
    """
    Parses the specified XML to retrieve the statistics for this table.
    """
    for stat in stats.getchildren():
        name = stat.get("name")
        value = stat.get("value")
        # TODO this really isn't very good at all.
        if name == "num_rows":
            self.__num_rows = int(value)
        elif name == "max_row_size":
            self.__max_row_size = int(value)
        elif name == "min_row_size":
            self.__min_row_size = int(value)
        elif name == "total_row_size":
            self.__total_row_size = int(value)
        else:
            raise ValueError("unknown table statistic '" + name + "'")

def __len__(self):
    """
    Implement the len(t) function.
    """
    self.verify_open()
    mode = self.get_open_mode()
    if mode == WT_READ:
        if self.__num_rows == 0:
            self.__num_rows = self.get_ll_object().get_num_rows()
    return self.__num_rows

def __getitem__(self, key):
    """
    Implements the t[key] function.
    """
    self.verify_open(WT_READ)
    t = self.get_ll_object()
    ret = None
    n = len(self)
    if isinstance(key, slice):
        ret = [self[j] for j in range(*key.indices(n))]
    elif isinstance(key, int):
        k = key
        if k < 0:
            k = n + k
        if k >= n:
            raise IndexError("table position out of range")
        ret = t.get_row(k)
    else:
        raise TypeError("table positions must be integers")
    return ret

def key_columns(self):
    """
    Returns the list of key columns.
    """
    return list(self.__key_columns)

def bin_widths(self):
    """
    Returns the list of bin widths in this index.
    """
    return list(self.__bin_widths)

def get_metadata(self):
    """
    Returns an ElementTree instance describing the metadata for this
    Index.
    """
    d = {"version":INDEX_METADATA_VERSION}
    root = ElementTree.Element("index", d)
    key_columns = ElementTree.Element("key_columns")
    root.append(key_columns)
    for j in range(len(self.__key_columns)):
        c = self.__key_columns[j]
        w = self.__bin_widths[j]
        if c.get_type() == WT_INT | c.get_type() == WT_UINT:
            w = int(w)
        d = {
            "name":c.get_name(),
            "bin_width":str(w),
        }
        element = ElementTree.Element("key_column", d)
        key_columns.append(element)
    return ElementTree.ElementTree(root)

def build(self, progress_callback=None, callback_rows=100):
    """
    Builds this index. If progress_callback is not None, invoke this
    calback after every callback_rows have been processed.
    """
    llo = self.get_ll_object()
    if progress_callback is not None:
        llo.build(progress_callback, callback_rows)
    else:
        llo.build()

def min_key(self, *k):
    """
    Returns the smallest key greater than or equal to the specified
    prefix.
    """
    if len(k) == 0:
        key = k
    else:
        key = self.key_to_ll(k)
    v = self.get_ll_object().get_min(key)
    return self.ll_to_key(v)

def max_key(self, *k):
    """
    Returns the largest index key less than the specified prefix.
    """
    if len(k) == 0:
        key = k
    else:
        key = self.key_to_ll(k)
    v = self.get_ll_object().get_max(key)
    return self.ll_to_key(v)

def key_to_ll(self, v):
    """
    Translates the specified tuple as a key to a tuple ready to
    for use in the low-level API.
    """
    cols = self.__key_columns
    if len(cols) == 1:
        l = [v]
    else:
        n = len(v)
        l = [None for j in range(n)]
        for j in range(n):
            l[j] = v[j]
            if isinstance(l[j], str):
                l[j] = l[j].encode()
    return tuple(l)

def __getitem__(self, key):
    k = self.__index.key_to_ll(key)
    return self.__index.get_ll_object().get_num_rows(k)

def __iter__(self):
    dvi = _wormtable.IndexKeyIterator(self.__index.get_ll_object())
    for v in dvi:
        yield self.__index.ll_to_key(v)

def __len__(self):
    n = 0
    dvi = _wormtable.IndexKeyIterator(self.__index.get_ll_object())
    for v in dvi:
        n += 1
    return n

def rows(self, table_columns):
    """
    Returns an iterator over the rows in this VCF file. Each row is a
    dictionary mapping column positions to their encoded string values.
    """
    # First we construct the mappings from the various parts of the
    # VCF row to the corresponding column index in the wormtable
    num_columns = len(table_columns)
    all_fixed_columns = VCF_FIXED_COLUMNS
    fixed_columns = []
    # weed out the columns that are not in the table
    for j in range(len(all_fixed_columns)):
        name = all_fixed_columns[j]
        if name in table_columns:
            fixed_columns.append((j, table_columns[name]))
    info_columns = {}
    genotype_columns = [{} for g in self.__genotypes]
    for k, v in table_columns.items():
        if COLUMN_SEPARATOR in k and v != 0:
            split = k.split(COLUMN_SEPARATOR)
            if split[0] == INFO:
                name = COLUMN_SEPARATOR.join(split[1:])
                info_columns[name] = v
            else:
                g = COLUMN_SEPARATOR.join(split[:-1])
                name = split[-1]
                index = self.__genotypes.index(g)
                genotype_columns[index][name] = v
    ref_index = 3
    alt_index = 4
    # Now we are ready to process the file.
    update_rows = self.get_progress_update_rows()
    num_rows = 0
    for s in self.get_input_file():
        row = [None for j in range(num_columns)]
        l = s.split()
        # Read in the fixed columns
        for vcf_index, wt_index in fixed_columns:
            if l[vcf_index] != MISSING_VALUE:
                row[wt_index] = l[vcf_index]
                if vcf_index in (ref_index, alt_index) and self.__truncate:
                    # truncate the REF/ALT column if necessary; this is a
                    # temporary workaround until more sophisticated
                    # truncation on a per column basis is implemented.
                    if len(l[vcf_index]) > 254:
                        row[wt_index] = l[vcf_index][:253] + b'+'
        # Now process the info columns.
        for mapping in l[7].split(b";"):
            tokens = mapping.split(b"=")
            name = tokens[0]
            if name in info_columns:
                col = info_columns[name]
                if len(tokens) == 2:
                    row[col] = tokens[1]
                else:
                    # This is a Flag column.
                    row[col] = b"1"
        # Process the genotype columns, if they exist
        if len(l) > 8:
            j = 0
            fmt = l[8].split(b":")
            for genotype_values in l[9:]:
                tokens = genotype_values.split(b":")
                if len(tokens) == len(fmt):
                    for k in range(len(fmt)):
                        if fmt[k] in genotype_columns[j]:
                            col = genotype_columns[j][fmt[k]]
                            tok = tokens[k]
                            # FIXME this is a hack to detect missing values
                            # in genotype columns. I'm not sure why anybody
                            # would do this, but we need it to parse the
                            # example VCF from the 1000genomes site.
                            if tok != MISSING_VALUE and tok != b".,.":
                                row[col] = tok
                j += 1
        yield row
        num_rows += 1
        if num_rows % update_rows == 0:
            self.update_progress()
    self.finish_progress()

def run(self):
    """
    Top level entry point.
    """
    if self.__schema is None:
        self.generate_schema()

    if os.path.exists(self.__destination):
        if self.__force:
            if os.path.isdir(self.__destination):
                shutil.rmtree(self.__destination)
            else:
                os.unlink(self.__destination)
        else:
            s = "'{0}' exists; use -f to overwrite".format(self.__destination)
            self.error(s)

    if self.__generate_schema:
        # copy the schema and we're done.
        shutil.copyfile(self.__schema, self.__destination)
    else:
        self.create_table()
        self.write_table()

def cleanup(self):
    """
    Cleans up any temporary files shuts down any running processes.
    """
    for f in self.__tmp_dirs:
        shutil.rmtree(f)
    for f in self.__tmp_files:
        os.unlink(f)
    if self.__reader is not None:
        self.__reader.close()
    if self.__writer is not None:
        self.__writer.close()

def format_size(self, n):
    """
    Returns a string formatting the specified value in bytes into a
    human readable format. Based on StackOverflow answer.
    """
    num = n
    for x in ['B  ','KiB','MiB','GiB']:
        if num < 1024.0:
            return "%3.1f %s" % (num, x)
        num /= 1024.0
    return "%3.1f %s" % (num, 'TiB')

