def dist(seq1, seq2):
    ''' Hamming distance '''
    assert len(seq1) == len(seq2)
    if seq1 == seq2:
        return 0

    return sum([c1 != c2 for c1, c2 in zip(seq1, seq2)])

def subseq(self, start, end):
    start = int(start)
    end   = int(end)
    assert start < end
    return self.seq[start:end]

def deletion(self, start, end):
    ''' deletes between start and end, bases at positions corresponding to start and end are kept '''
    start = int(start)
    end   = int(end)
    assert start < end
    self.seq = self.seq[:start] + self.seq[end:]

def duplication(self,start,end,fold=1):
    ''' duplicates sequence between start and end, bases at start and end positions are not included '''
    start = int(start)
    end   = int(end)
    assert start < end
    dupseq = self.seq[start:end]
    for i in range(fold):
        dupseq = dupseq + self.seq[start:end]
    self.seq = self.seq[:start] + dupseq + self.seq[end:]

def fusion(self, loc1, other, loc2, flip1=False, flip2=False):
    loc1 = int(loc1)
    loc2 = int(loc2)

    loc1_seq = self.seq[:loc1]
    loc2_seq = other.seq[loc2:]

    if flip1:
        loc1_seq = rc(self.seq[loc1:])

    if flip2:
        loc2_seq = rc(other.seq[:loc2])

    self.seq = loc1_seq + loc2_seq

def find_mate(read, bam):
    ''' AlignmentFile.mate() can return a non-primary alignment, so use this function instead '''
    chrom = read.next_reference_name
    for rec in bam.fetch(chrom, read.next_reference_start, read.next_reference_start+1):
        if rec.query_name == read.query_name and rec.reference_start == read.next_reference_start:
            if not rec.is_secondary and bin(rec.flag & 2048) != bin(2048):
                if rec.is_read1 != read.is_read1:
                    return rec
    return None

def mutate(args, log, bamfile, bammate, chrom, mutstart, mutend, mutpos_list, avoid=None, mutid_list=None, is_snv=False, mutbase_list=None, is_insertion=False, is_deletion=False, ins_seq=None, reffile=None, indel_start=None, indel_end=None):
    assert mutend > mutstart, "mutation start must occur before mutation end"

    hasSNP = False

    outreads = od()
    mutreads = od()
    mutmates = od()

    region = 'haplo_' + chrom + '_' + str(mutstart) + '_' + str(mutend)

    maxfrac = None

    for pcol in bamfile.pileup(reference=chrom, start=mutstart-1, end=mutend+1, max_depth=int(args.maxdepth), ignore_overlaps=False):
        if pcol.pos:
            if args.ignorepileup and (pcol.pos < mutstart-1 or pcol.pos > mutend+1):
                continue

            refbase = reffile.fetch(chrom, pcol.pos-1, pcol.pos)
            basepile = ''
            for pread in pcol.pileups:
                if avoid is not None and pread.alignment.qname in avoid:
                    logger.warning(region + " dropped mutation due to read in --avoidlist " + pread.alignment.qname)
                    return True, False, maxfrac, {}, {}, {}

                # only consider primary alignments
                if pread.query_position is not None and not pread.alignment.is_secondary and bin(pread.alignment.flag & 2048) != bin(2048):
                    basepile += pread.alignment.seq[pread.query_position-1]
                    pairname = 'F' # read is first in pair
                    if pread.alignment.is_read2:
                        pairname = 'S' # read is second in pair
                    if not pread.alignment.is_paired:
                        pairname = 'U' # read is unpaired

                    extqname = ','.join((pread.alignment.qname,str(pread.alignment.pos),pairname))

                    if pcol.pos+1 in mutpos_list:

                        if not pread.alignment.is_secondary and bin(pread.alignment.flag & 2048) != bin(2048) and not pread.alignment.mate_is_unmapped:
                            outreads[extqname] = pread.alignment
                            mutid = mutid_list[mutpos_list.index(pcol.pos+1)]

                            if is_snv:
                                if extqname not in mutreads:
                                    mutreads[extqname] = pread.alignment.seq

                                mutbase = mutbase_list[mutpos_list.index(pcol.pos+1)]
                                mutbases = list(mutreads[extqname])
                                mutbases[pread.query_position] = mutbase
                                mutread = ''.join(mutbases)
                                mutreads[extqname] = mutread

                            if is_insertion:
                                mutreads[extqname] = makeins(pread.alignment, indel_start, ins_seq)

                            if is_deletion:
                                mutreads[extqname] = makedel(pread.alignment, chrom, indel_start, indel_end, reffile)

                            mate = None
                            if not args.single:
                                try:
                                    mate = find_mate(pread.alignment, bammate)
                                except ValueError:
                                    raise ValueError('cannot find mate reference chrom for read %s, is this a single-ended BAM?' % pread.alignment.qname)

                                if mate is None:
                                    logger.warning(mutid + " warning: no mate for " + pread.alignment.qname)
                                    if args.requirepaired:
                                        logger.warning(mutid + " skipped mutation due to --requirepaired")
                                        return True, False, {}, {}, {}

                            if extqname not in mutmates:
                                mutmates[extqname] = mate

                            log.write(" ".join(('read',extqname,mutreads[extqname],"\n")))

                        if len(mutreads) > int(args.maxdepth):
                            logger.warning("depth at site is greater than cutoff, aborting mutation")
                            return True, False, maxfrac, {}, {}, {}

            # make sure region doesn't have any changes that are likely SNPs
            # (trying to avoid messing with haplotypes)
            maxfrac = 0.0
            hasSNP  = False

            basepile = countBaseAtPos(args.bamFileName,chrom,pcol.pos,mutid=region)
            if basepile:
                majb = majorbase(basepile)
                minb = minorbase(basepile)

                frac = float(minb[1])/(float(majb[1])+float(minb[1]))
                if minb[0] == majb[0]:
                    frac = 0.0
                if frac > maxfrac:
                    maxfrac = frac
                if frac > float(args.snvfrac):
                    logger.warning(region + " dropped for proximity to SNP, nearby SNP MAF: " + str(frac)  + " (max snv frac: " + args.snvfrac + ")")
                    hasSNP = True
            else:
                logger.warning(region + " could not pileup for region: " + chrom + ":" + str(pcol.pos))
                if not args.ignorepileup:
                    hasSNP = True

    if maxfrac is None:
        logger.warning("could not pile up over region: %s" % region)
        return True, False, maxfrac, {}, {}, {}

    return False, hasSNP, maxfrac, outreads, mutreads, mutmates # todo: convert to class

def __init__(self, eid):
    self.eid = eid
    self.reads = {} # read names

def getReadNames(self,seqs):
    for src, read in self.reads.items():
        self.reads[src].name = seqs.srcread[src]
        self.reads[src].seq  = seqs.seqmap[seqs.srcread[src]]

def __str__(self):
    output = []
    for eid, read in self.reads.items():
        output.append(str(read))
    return '\n'.join(output)

def __str__(self):
    output = ""
    for name, seq in self.seqmap.items():
        output += ">" + name + "\n" + seq + "\n"
    return output

def cleanup(read,orig,RG):
    '''
    fixes unmapped reads that are marked as 'reverse'
    fill in read group at random from existing RGs if 
    RG tags are present in .bam header 
    '''

    if read.is_unmapped and read.is_reverse:
        read.is_reverse = False
        qual = read.qual
        read.seq  = rc(read.seq)
        read.qual = qual[::-1]
    if read.mate_is_unmapped and read.mate_is_reverse:
        read.mate_is_reverse = False
        # mate seq/qual should be caught by the above logic

    if RG:
        hasRG = False
        if read.tags is not None:
            for tag in read.tags:
                if tag[0] == 'RG':
                    hasRG = True

        # use RG from original read if it exists
        if orig is not None:
            if not hasRG and orig.tags is not None:
                if orig.has_tag('RG'):
                    read.set_tag('RG', orig.get_tag('RG'), "Z")
                    hasRG = True

        if not hasRG:
            # give up and add random read group from list in header (e.g. for simulated reads)
            newRG = RG[random.randint(0,len(RG)-1)]
            read.set_tag('RG', newRG, "Z")

    return read

def get_RGs(bam):
    '''return list of RG IDs'''
    RG = []
    if 'RG' in bam.header:
        for headRG in bam.header['RG']:
            RG.append(headRG['ID'])
    return RG

def compare_ref(targetbam, donorbam):
    ''' if targetbam and donorbam are aligned to different references 
        and the references are in a different order it's a problem
    '''
    for ref in targetbam.references:
        if ref not in donorbam.references or donorbam.gettid(ref) != targetbam.gettid(ref):
            logger.error("contig mismatch: %s\n" % ref)
            return False
    return True

def fetchregions(infn, outfn, invcf, fasta_ref, window=1000):
    inbam  = pysam.AlignmentFile(infn, reference_filename=fasta_ref)
    outbam = pysam.AlignmentFile(outfn, 'wb', template=inbam)

    vcfh = vcf.Reader(filename=invcf)

    for rec in vcfh:
        start = rec.POS - window
        end   = rec.POS + window

        if 'END' in rec.INFO:
            end = int(rec.INFO.get('END')[0]) + window

        if rec.CHROM not in inbam.references:
            logging.warn("WARNING: " + rec.CHROM + " contig or chromosome not in " + infn + "\n")
            continue

        for read in inbam.fetch(rec.CHROM, start, end):
            outbam.write(read)

    inbam.close()
    outbam.close()

def split(inbamfn, keep_secondary=False, keep_supplementary=False, seed=None):

    if seed is not None:
        random.seed(seed)

    else:
        seed = int(random.random()*1000)
        logger.info("using seed: %d" % seed)
        random.seed(seed)


    assert inbamfn.endswith('.bam')
    outbam1fn = sub('.bam$', '.pick1.bam', inbamfn)
    outbam2fn = sub('.bam$', '.pick2.bam', inbamfn)

    inbam = pysam.AlignmentFile(inbamfn)
    outbam1 = pysam.AlignmentFile(outbam1fn, 'wb', template=inbam)
    outbam2 = pysam.AlignmentFile(outbam2fn, 'wb', template=inbam)

    lastread = None

    reads = dd(list) 

    skip_secondary = 0
    skip_supplementary = 0

    for read in inbam.fetch(until_eof=True):
        if (read.is_secondary and args.secondary) or (read.is_supplementary and args.supplementary) or (not read.is_supplementary and not read.is_secondary):
            if lastread is not None and read.qname == lastread.qname:
                reads[read.qname].append(read)

            else:
                if lastread is not None:
                    ob = None
                    if random.random() > 0.5:
                        ob = outbam1
                    else:
                        ob = outbam2

                    for outread in reads[lastread.qname]:
                        ob.write(outread)

                    del reads[lastread.qname]
                reads[read.qname].append(read)
            lastread = read
        elif read.is_secondary:
            skip_secondary += 1
        else:
            skip_supplementary +=1


    ob = None
    if random.random() > 0.5:
        ob = outbam1
    else:
        ob = outbam2

    for read in reads[lastread.qname]:
        ob.write(read)

    outbam1.close()
    outbam2.close()
    inbam.close()

    if not args.secondary and skip_secondary >= 1:
        logger.info("skipped %d secondary reads" % skip_secondary)

    if not args.supplementary and skip_supplementary >= 1:
        logger.info("skipped %d supplementary reads" % skip_supplementary)

def check_java():
