def getsegs(bam, mindepth, minlength):
    seglist = []
    cmd = ['samtools', 'mpileup', bam]

    p = subprocess.Popen(cmd, stdout=subprocess.PIPE)

    seg = {'chrom': None, 'start': None, 'end': None}

    for line in p.stdout:
        chrom, pos, base, depth = line.strip().split()[:4]

        depth = int(depth)
        pos   = int(pos)

        if seg['chrom'] != chrom:
            if seg['chrom'] is not None:
                if seg['end'] - seg['start'] >= minlength:
                    seglist.append(seg)

            seg = {'chrom': chrom, 'start': pos, 'end': pos}

        else:
            if pos == seg['end']+1 and depth > mindepth:
                seg['end'] = pos

            else:
                if seg['end'] - seg['start'] >= minlength:
                    seglist.append(seg)
                seg = {'chrom': chrom, 'start': pos, 'end': pos}

    return seglist

def main(args):
    assert os.path.exists(args.bam + '.bai'), ".bai index not found for BAM: " + args.bam

    seglist = getsegs(args.bam, int(args.depth), int(args.length))
    for seg in seglist:
        print('\t'.join((seg['chrom'], str(seg['start']), str(seg['end']))))

def cmp(self,ivl):
    if self.chr == ivl.chr:
        if (self.start <= ivl.start and self.end >= ivl.start) or (self.start <= ivl.end and self.end >= ivl.end):
            if self.eq(ivl):
                return False
            return True
        else:
            return False
    else:
        return False

def eq(self,ivl):
    if self.chr == ivl.chr and self.start == ivl.start and self.end == ivl.end and self.info == ivl.info:
        return True
    return False

def __str__(self):
    out = "\t".join((self.chr,str(self.start+pad),str(self.end-pad))) + "\t" + " ".join(self.info)
    return out

def match(subrec, trurec, vtype='SNV'):
    assert vtype in ('SNV', 'SV', 'INDEL')

    if vtype == 'SNV' and subrec.is_snp and trurec.is_snp:
        if subrec.POS == trurec.POS and subrec.REF == trurec.REF and subrec.ALT == trurec.ALT:
            return True

    if vtype == 'INDEL' and subrec.is_indel and trurec.is_indel:
        if subrec.POS == trurec.POS and subrec.REF == trurec.REF and subrec.ALT == trurec.ALT:
            return True

    if vtype == 'SV' and subrec.is_sv and trurec.is_sv:
        trustart, truend = expand_sv_ends(trurec)
        substart, subend = expand_sv_ends(subrec)

        # check for overlap
        if min(truend, subend) - max(trustart, substart) > 0:
            return True

    return False

def expand_sv_ends(rec):
    ''' assign start and end positions to SV calls using conf. intervals if present '''
    startpos, endpos = rec.start, rec.end
    assert rec.is_sv

    try:
        endpos = int(rec.INFO.get('END')[0])

        if rec.INFO.get('CIPOS'):
            ci = map(int, rec.INFO.get('CIPOS'))
            if ci[0] < 0:
                startpos += ci[0]

        if rec.INFO.get('CIEND'):
            ci = map(int, rec.INFO.get('CIEND')) 
            if ci[0] > 0:
                endpos += ci[0]

    except TypeError as e:
        logger.error("error expanding sv interval: " + str(e) + " for record: " + str(rec) + "\n")

    if startpos > endpos:
        endpos, startpos = startpos, endpos

    return startpos, endpos

def relevant(rec, vtype, ignorechroms):
    ''' Return true if a record matches the type of variant being investigated '''
    rel = (rec.is_snp and vtype == 'SNV') or (rec.is_sv and vtype == 'SV') or (rec.is_indel and vtype == 'INDEL')
    return rel and (ignorechroms is None or rec.CHROM not in ignorechroms)

def passfilter(rec, disabled=False):
    ''' Return true if a record is unfiltered or has 'PASS' in the filter field (pyvcf sets FILTER to None) '''
    if disabled:
        return True
    if rec.FILTER is None or rec.FILTER == '.' or not rec.FILTER:
        return True
    return False

def svmask(rec, vcfh, truchroms):
    ''' mask snv calls in sv regions '''
    if rec.is_snp and rec.CHROM in truchroms:
        for overlap_rec in vcfh.fetch(rec.CHROM, rec.POS-1, rec.POS):
            if overlap_rec.is_sv:
                return True
    return False

def var_dist(v1, v2):
    """compute absolute distance between two variants
    """
    assert v1.CHROM == v2.CHROM
    return abs(v1.POS-v2.POS)

def get_close_matches(var, vcf_fh, win, indels_only=True):
    """Find close matches for variant (PyVCF record var) in file (PyVCF
    VCFReader vcf_fh) within given window win and return as list of
    item,distance tuples, sorted ascendingly by distance.

    """

    matches = list(vcf_fh.fetch(var.CHROM, var.POS-win, var.POS+1+win))
    if indels_only:
        matches = [m for m in matches if m.is_indel]
    if len(matches) == 0:
        return []

    dist_map = [(m, var_dist(m, var)) for m in matches]
    return sorted(dist_map, key=lambda x: x[1])

def evaluate(submission, truth, vtype='SNV', reffa=None, ignorechroms=None, ignorepass=False, 
             fp_vcf=None, fn_vcf=None, tp_vcf=None,
             debug=False):
    ''' return stats on sensitivity, specificity, balanced accuracy '''

    assert vtype in ('SNV', 'SV', 'INDEL')
    subvcfh = vcf.Reader(filename=submission)
    truvcfh = vcf.Reader(filename=truth)

    fpvcfh = fnvcfh = tpvcfh = None
    if fp_vcf:
        fpvcfh = vcf.Writer(open(fp_vcf, 'w'), template=subvcfh)
    if fn_vcf:
        fnvcfh = vcf.Writer(open(fn_vcf, 'w'), template=subvcfh)
    if tp_vcf:
        tpvcfh = vcf.Writer(open(tp_vcf, 'w'), template=subvcfh)

    reffa_fh = None
    if reffa:
        reffa_fh  = pysam.Fastafile(reffa)
        if debug:
            print("DEBUG: Using haplotype aware indel comparison")

    tpcount = 0
    fpcount = 0
    subrecs = 0
    trurecs = 0

    truchroms = {}
    fns = OrderedDict()

    ''' count records in truth vcf, track contigs/chromosomes '''
    for trurec in truvcfh:
        if relevant(trurec, vtype, ignorechroms):
            trurecs += 1
            truchroms[trurec.CHROM] = True
            fns[str(trurec)] = trurec

    used_truth = {} # keep track of 'truth' sites used, they should only be usable once

    ''' parse submission vcf, compare to truth '''
    for subrec in subvcfh:
        if passfilter(subrec, disabled=ignorepass):
            if subrec.is_snp and vtype == 'SNV':
                if not svmask(subrec, truvcfh, truchroms):
                    subrecs += 1
            if subrec.is_sv and vtype == 'SV':
                subrecs += 1
            if subrec.is_indel and vtype == 'INDEL':
                subrecs += 1

        matched = False

        startpos, endpos = subrec.start, subrec.end

        if vtype == 'SV' and subrec.is_sv:
            startpos, endpos = expand_sv_ends(subrec)
        try:
            if relevant(subrec, vtype, ignorechroms) and passfilter(subrec, disabled=ignorepass) and subrec.CHROM in truchroms:
                for trurec in truvcfh.fetch(subrec.CHROM, startpos, end=endpos):
                    if match(subrec, trurec, vtype=vtype) and str(trurec) not in used_truth:
                        matched = True
                if not matched and subrec.is_indel and reffa_fh:# try haplotype aware comparison
                    window = 100
                    for (trurec, _) in get_close_matches(subrec, truvcfh, window, indels_only=True):
                        if str(trurec) in used_truth:
                            continue
                        if have_identical_haplotypes(subrec, trurec, reffa_fh):
                            matched = True
                            if debug:
                                print("DEBUG: Rescuing %s which has same haplotype as %s" % (subrec, trurec))
                            break
            if matched:
                used_truth[str(trurec)] = True

        except ValueError as e:
            logger.error("Warning: " + str(e) + "\n")

        if matched:
            tpcount += 1
            if tpvcfh:
                tpvcfh.write_record(subrec)
            if str(trurec) in fns.keys():
                del fns[str(trurec)]            
        else:
            if relevant(subrec, vtype, ignorechroms) and passfilter(subrec, disabled=ignorepass) and not svmask(subrec, truvcfh, truchroms): 
                fpcount += 1 # FP counting method needs to change for real tumors
                if fpvcfh:
                    fpvcfh.write_record(subrec)


    if fnvcfh:
        for fn in fns.values():
            fnvcfh.write_record(fn)


    print(f"tpcount, fpcount, subrecs, trurecs: {tpcount},{fpcount},{subrecs},{trurecs}")

    recall = float(tpcount) / float(trurecs)
    if tpcount+fpcount > 0:
        precision = float(tpcount) / float(tpcount + fpcount)
    else:
        precision = 0.0
    #fdr       = 1.0 - float(fpcount) / float(subrecs)
    f1score   = 0.0 if tpcount == 0 else 2.0*(precision*recall)/(precision+recall)

    for fh in [fpvcfh, fnvcfh, tpvcfh]:
        if fh:
            fh.close()

    return precision, recall, f1score

def getRG(tags):
    ''' fetch RG, tags is from a pysam.AlignedRead.tags, returns RG name '''
    for tag, val in tags:
        if tag == 'RG':
            return val
    return None

def putRG(tags, rg):
    ''' replace RG, tags is from a pysam.AlignedRead.tags, returns list of tags '''
    out = []
    for tag, val in tags:
        if tag == 'RG':
            out.append((tag, rg))
        else:
            out.append((tag, val))
    return out

def samrec(read, bam, IDRG, newname=None):
    ''' output sam formatted record from pysam.AlignedRead '''
    fields = []

    if newname is not None:
        fields.append(newname)
    else:
        fields.append(read.qname)

    fields.append(str(read.flag))

    if read.is_unmapped:
        if read.mate_is_unmapped:
            fields.append('*')
        else:
            fields.append(bam.getrname(read.rnext))
    else:
        fields.append(bam.getrname(read.tid))

    if read.is_unmapped:
        if read.mate_is_unmapped:
            fields.append('0') # was 0
        else:
            fields.append(str(read.mpos+1)) #avoid OBOE, pysam is always 0-based, SAM is 1-based, BAM is 0-based.
        fields.append('0') # was 0
    else:
        fields.append(str(read.pos+1)) #avoid OBOE
        fields.append(str(read.mapq))

    # unmapped reads should have '*' as CIGAR string
    if read.is_unmapped:
        fields.append('*')
    else:
        fields.append(read.cigarstring)

    if read.tid == read.rnext:
        fields.append('=')
    else:
        if read.is_unmapped or read.mate_is_unmapped:
            fields.append('=')
        else:
            fields.append(bam.getrname(read.rnext))

    if read.mate_is_unmapped:
        if read.is_unmapped:
            fields.append('0') # was 0
        else:
            fields.append(str(read.pos+1)) # avoid OBOE
    else:
        fields.append(str(read.mpos+1)) # avoid OBOE

    if read.is_unmapped or read.mate_is_unmapped:
        fields.append('0')
    else:
        fields.append(str(read.isize))
    fields.append(read.seq)
    fields.append(read.qual)

    for tag in read.tags:
        tagname, tagval = tag
        # retain only certain tags
        if tagname in ('NM', 'MD', 'AS', 'XS', 'RG'):
            tagtype = None

            # note, python has no 'char' type so tags with 'A' type will be converted to 'Z'
            if type(tagval) == type('a'):
                tagtype = 'Z'
            if type(tagval) == type(1):
                tagtype = 'i'
            if type(tagval) == type(1.0):
                tagtype = 'f'

            if tagname == 'RG':
                if tagval not in IDRG:
                    logging.error("ERROR: read group: " + tagval + " not found!\n")
                assert tagval in IDRG # make sure readgroup is value (i.e. in the header)
                tagval = IDRG[tagval]

            if tagtype is not None:
                fields.append(':'.join((tagname, tagtype, str(tagval))))

    return '\t'.join(fields)

def pick(self, mutlen, avoidN=False, usebed=False):
    ''' return a random chromosome and position '''
    goodmut = False

    if usebed:
        seg = random.choice(self.bed)
        rpos = int(random.uniform(seg[1], seg[2]))
        return seg[0], rpos, rpos + mutlen

    else:
        goodmut = False
        while not goodmut:
            rchrom = random.choice(self.chrmap)
            rpos   = int(random.uniform(1, self.chrlen[rchrom]))

            if avoidN and 'N' not in self.ref.fetch(rchrom, rpos-1, rpos+mutlen):
                goodmut = True

            if not avoidN:
                goodmut = True

        return rchrom, rpos, rpos + mutlen

def randomseq(len):
    ''' make a random DNA sequence '''
    return ''.join([random.choice(['A','T','G','C']) for _ in range(int(len))])

def betafunc(a,b):
    ''' return appropriate function from random class '''
    return lambda : random.betavariate(float(a), float(b))

def overlap(self, other, sep):
    start = self.start - sep
    end   = self.end + sep

    if min(end, other.end) - max(start, other.start) >= 0:
        return True
    return False

def __lt__(self, other):
    if self.chrom != other.chrom:
        return self.chrom < other.chrom
    else:
        return self.start < other.start

def mut(base, altbase):
    """ change base to something different
    """

    bases = ('A','T','C','G')
    base = base.upper()
    if base not in bases or (altbase is not None and altbase not in ['A','T','G','C']):
        raise ValueError("ERROR base passed to mut(): " + str(base) + " not one of (A,T,C,G)\n")

    if altbase is not None:
        return altbase

    else:
        alt = base
        while alt == base:
            alt = bases[int(random.uniform(0,4))]
        return alt

def singleseqfa(file,mutid='null'):
    with open(file, 'r') as fasta:
        header = None
        seq = ''
        for line in fasta:
            line = line.strip()
            if line.startswith('>'):
                if header is not None:
                    logger.warning("%s multiple entries found in %s only using the first" % (mutid, file))
                header = line.lstrip('>')
            else:
                seq += line
    return seq

def load_inslib(infa):
    seqdict = {}

    with open(infa, 'r') as fa:
        seqid = ''
        seq   = ''
        for line in fa:
            if line.startswith('>'):
                if seq != '':
                    seqdict[seqid] = seq
                seqid = line.lstrip('>').strip()
                seq   = ''
            else:
                assert seqid != ''
                seq = seq + line.strip()

    if seqid not in seqdict and seq != '':
        seqdict[seqid] = seq

    return seqdict

def discordant_fraction(bamfile, fasta_ref, chrom, start, end):
    r = 0
    d = 0
    bam = pysam.AlignmentFile(bamfile, reference_filename=fasta_ref)
    for read in bam.fetch(chrom, start, end):
        r += 1
        if not read.is_proper_pair:
            d += 1

    if r > 0:
        return float(d)/float(r)
    else:
        return 0.0

def locate_contig_pos(refstart, refend, user_start, user_end, contig_len, maxlibsize):
    contig_start = None
    contig_end = None

    if user_start - refstart > maxlibsize:
        contig_start = (user_start - refstart)

    if refend - user_end > maxlibsize:
        contig_end = contig_len - (refend - user_end)

    return contig_start, contig_end

def merge_multi_trn(args, alignopts, pair, chrom, start, end, vaf):
    assert len(pair) == 2

    mutid = os.path.basename(pair[0]).split('.')[0]

    outbamfn = '%s/%s.%s.merged.bam' % (args.tmpdir, mutid, str(uuid4()))
    bams = [pysam.AlignmentFile(bam, reference_filename=args.refFasta) for bam in pair]
    outbam = pysam.AlignmentFile(outbamfn, 'wb', template=bams[0])

    readbins = {} # randomly assorted reads into bam sources 0 and 1

    for bam in bams:
        for read in bam.fetch(until_eof=True):
            readbins[read.query_name] = random.choice([0,1])

        bam.close()

    bams = [pysam.AlignmentFile(bam, reference_filename=args.refFasta) for bam in pair]

    for i, bam in enumerate(bams):
        for read in bam.fetch(until_eof=True):
            if readbins[read.query_name] == i:
                outbam.write(read)

    outbam.close()

    # cleanup
    for fn in pair:
        os.remove(fn)

    return outbamfn

def _checkoptions(name, options):
    ''' checks if necessary options have been specified '''
    if name == 'novoalign':
        if 'novoref' not in options:
            raise ValueError("ERROR '--aligner novoalign' requires '--alignopts novoref:path_to_novoalign_reference' to be set\n")
    elif name == 'gsnap':
        if 'gsnaprefdir' not in options or 'gsnaprefname' not in options:
            raise ValueError("ERROR '--aligner gsnap' requires '--alignopts gsnaprefdir:GSNAP_reference_dir,gsnaprefname:GSNAP_ref_name\n")
    elif name == 'STAR':
        if 'STARrefdir' not in options:
            raise ValueError("ERROR '--aligner STAR' requires '--alignopts STARrefdir:/path/to/STAR_reference_dir\n")
    elif name == 'bowtie2':
        if 'bowtie2ref' not in options:
            raise ValueError("ERROR '--aligner bowtie2' requires '--alignopts bowtie2ref:bowtie2_ref_basepath\n")
    elif name == 'minimap2':
        if 'x' not in options:
            raise ValueError("ERROR '--aligner minimap2' requires '--alignopts x:map-pb or x:map-ont\n")
    elif name not in SUPPORTED_ALIGNERS:
        raise ValueError("ERROR unsupported aligner: " + name)

def remap_bam(name, bamfn, fastaref, options, mutid='null', threads=1, paired=True, picardjar=None, deltmp=True):
    ''' remap bam file with supported alignment method. "options" param is a dict of aligner-specific required options '''
    fastqs = bamtofastq(bamfn, picardjar, threads=threads, paired=paired, twofastq=(name not in INTERLEAVED_FASTQ_ALIGNERS))

    if len(fastqs) == 2:
        fq1, fq2 = fastqs
    else:
        fq1 = fastqs[0]
        fq2 = None

    remap_fastq(name, fq1, fastaref, bamfn, options, fq2=fq2, mutid=mutid, threads=threads, deltmp=deltmp)

def remap_fastq(name, fq1, fastaref, outbam, options, fq2=None, mutid='null', threads=1, deltmp=True):
    ''' remap bam file with supported alignment method. "options" param is a dict of aligner-specific required options '''

    _checkoptions(name, options)

    basefn = "tmp." + str(uuid4())
    sam_out = basefn + '.sam'
    sort_tmp = basefn + '.sort.bam'

    logger.info(mutid + " aligning " + fq1 + ',' + fq2 + " with " + name)
    if name == 'backtrack':
        _run_backtrack(fq1, fastaref, sam_out, fq2=fq2, threads=threads)
    elif name == 'mem':
        _run_bwa_mem(fq1, fastaref, sam_out, fq2=fq2, threads=threads)
    elif name == 'novoalign':
        _run_novoalign(fq1, sam_out, options['novoref'], fq2=fq2)
    elif name == 'gsnap':
        _run_gsnap(fq1, sam_out, options['gsnaprefdir'], options['gsnaprefname'], fq2=fq2, threads=threads)
    elif name == 'STAR':
        _run_STAR(fq1, sam_out, options['STARrefdir'], fq2=fq2)
    elif name == 'bowtie2':
        _run_bowtie2(fq1, options['bowtie2ref'], sam_out, fq2=fq2)
    elif name == 'tmap':
        _run_tmap(fq1, fastaref, sam_out, fq2=fq2, threads=threads)
    elif name == 'bwakit':
        _run_bwakit(fq1, fastaref, sam_out, fq2=fq2, threads=threads)
    elif name == 'minimap2':
        # minimap2 requires interleaved fastq
        if fq2 is not None:
            double_fastq_to_interleaved(fq1, fq2, fq1 + '.interleaved')
            os.remove(fq1)
            os.remove(fq2)
            fq1 = fq1 + '.interleaved'
        _run_minimap2(fq1, fastaref, sam_out, options['x'], threads=threads)
    else:
        raise ValueError("ERROR: " + name + " is not a supported aligner for remapping.")

    sort_cmd = ['samtools', 'sort', '-@', str(threads), '-T', sort_tmp, '-o', outbam, sam_out]
    idx_cmd = ['samtools', 'index', outbam]
    subprocess.check_call(sort_cmd)
    subprocess.check_call(idx_cmd)

    if deltmp:
        os.remove(fq1)
        os.remove(sam_out)
        if fq2 is not None:
            os.remove(fq2)

def _run_bwa_mem(fq1, fastaref, sam_out, fq2=None, threads=1):
    if fq2 is None:
        sam_cmd = ['bwa', 'mem', '-t', str(threads), '-M', '-Y', fastaref, fq1]
    else:
        sam_cmd = ['bwa', 'mem', '-t', str(threads), '-M', '-Y', fastaref, fq1, fq2]
    with open(sam_out, 'w') as sam:
        subprocess.check_call(sam_cmd, stdout=sam)

def _run_novoalign(fq1, sam_out, novoref, fq2=None):
    sam_cmd = ['novoalign', '-F', 'STDFQ', '-r', 'Random', '-d', novoref, '-oSAM', '-f', fq1]
    if fq2 is not None:
        sam_cmd.append(fq2)
    with open(sam_out, 'w') as sam:
        subprocess.check_call(sam_cmd, stdout=sam)

def _run_STAR(fq1, sam_out, STARrefdir, fq2=None):
    sam_cmd = ['STAR', '--genomeLoad', 'LoadAndKeep', '--genomeDir', STARrefdir, '--outFileNamePrefix', sam_out, '--readFilesIn', fq1]
    if fq2 is not None:
        sam_cmd.append(fq2)
    subprocess.check_call(sam_cmd)
    shutil.move(sam_out + 'Aligned.out.sam', sam_out)

def _run_bowtie2(fq1, bowtie2ref, sam_out, fq2=None):
    sam_cmd = ['bowtie2', '-x', bowtie2ref, '-S', sam_out, '-1', fq1]
    if fq2 is not None:
        sam_cmd += ['-2', fq2]
    subprocess.check_call(sam_cmd)

def _run_tmap(fq1, fastaref, sam_out, fq2=None, threads=1):
    if fq2 is not None:
        raise ValueError('tmap is not supported for paired-end reads.')
    sam_cmd = ['tmap', 'mapall', '-f', fastaref, '-r', fq1, '-n', str(threads), '-v', '-u', '-o', '0', 'stage1', 'map4']
    with open(sam_out, 'w') as sam:
        subprocess.check_call(sam_cmd, stdout=sam)

def _run_bwakit(fq1, fastaref, sam_out, fq2=None, threads=1):
    sam_cmd = ['run-bwamem', '-t', str(threads), '-o', sam_out, '-H', fastaref, fq1]
    if fq2 is not None:
        sam_cmd.append(fq2)
    # It is not a SAM file, but it should work
    shutil.move(sam_out + '.aln.bam', sam_out)

